class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        pos, d = [0,0], "N"
        def move(d, pos, instructions):
            for i in instructions:
                if i == "G":
                    if d == "N": pos[1] += 1
                    elif d == "S": pos[1] -= 1
                    elif d == "W": pos[0] -= 1
                    else: pos[0] += 1
                elif i == "L":
                    if d == "N": d = "W"
                    elif d == "W": d = "S"
                    elif d == "S": d = "E"
                    else: d = "N"
                else:
                    if d == "N": d = "E"
                    elif d == "W": d = "N"
                    elif d == "S": d = "W"
                    else: d = "S"
            return (d, pos)
        for i in range(4):
            d, pos = (move(d, pos, instructions))
        return True if pos == [0,0] else False

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        directions = [[ 1, 0], [0, -1], [-1, 0], [0, 1]]
        x, y, i = 0, 0, 0
        for instruction in instructions:
            if instruction == 'R':
                i = (i+1) % 4
            elif instruction == 'L':
                i = (i-1) % 4
            else:
                x += directions[i][0]
                y += directions[i][1]
        return (x == 0 and y == 0) or i > 0

class Solution:
    def gardenNoAdj(self, N, paths):
        result = [0]*N
        G = [[] for i in range(N)]
        for x, y in paths:
            G[x-1].append(y-1)
            G[y-1].append(x-1)
        for i in range(N):
            result[i] = ({1, 2, 3, 4} - {result[j] for j in G[i]}).pop()
        return result

